def save(name,value):(r/name).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def sha(data):return hashlib.sha256(data).hexdigest()
def reject_constant(x):raise ValueError('non-JSON constant: '+x)
def no_duplicate(pairs):
    result={}
    for k,v in pairs:
        if k in result:raise ValueError('duplicate JSON key: '+k)
        result[k]=v
    return result
def load(path):return json.loads(path.read_text(encoding='utf-8'),object_pairs_hook=no_duplicate,parse_constant=reject_constant)
def xml_read(path):
    cases=ET.parse(path).findall('.//testcase');ids=[x.get('classname').replace('.','/')+'.py::'+x.get('name') for x in cases]
